#!/usr/bin/env python
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
# -*- coding: utf-8 -*-
"""qc_base_check.py — Obsidian Bases（`*.base`）的「选中集合 + 漂移」校验器。

**为什么需要它**：`.base` 是 Obsidian 核心插件 Bases 的**视图定义**，不是数据。
它既不像 `.index/` 那样可以重建，也没有任何「刷新」按钮——但**它的失新是完全静默的**：

  1. **视图级过滤器被误改** —— 会静默把某个视图的选中集合缩到很小（Obsidian 不报错）。
     事故实例（2026-10-10）：`数据库.base` 的「Matsci 总览」被塞进一条
     `file.hasLink("wiki/topics/化学大模型能力评估全景.md")`，724 页总览**只剩 33 页**。
  2. **依赖字段缺失** —— frontmatter 少了 `year`/`journal`/`evidence_base`…
     页面会在视图里**删行或显示空白**，同样不报错。
  3. **命中数漂移** —— ingest 后页面数应增长；若**不增反减**，通常是过滤器坏了。

本工具做三件事（**只读，绝不改 `.base`**）：
  A. 用**自研的小型 Base 过滤器解释器**把每个 `.base` 的顶层 `filters` 在
     Python 侧重算一遍，得到**选中页面集合**与计数（对照 §维护纪律 1：
     「改 `.base` 后必须验证选中集合，Obsidian 不报『筛出 0 条』」）。
  B. 结构不变量：列出每个视图的**视图级 `filters`**（它们是「静默收窄」的高发地）。
  C. 漂移检测：与 `.qc/base_state.json` 基线快照比对。**过滤器签名变化 = 报警**
     （有人在库外动了选择逻辑）；计数变化 = 提示（ingest 后应增长）。

用法：
  python tools/qc_base_check.py                # 干跑：重算 + 比对 + 更新基线
  python tools/qc_base_check.py --check        # 只比对，不更新基线
  python tools/qc_base_check.py --json         # 机器可读
  python tools/qc_base_check.py --verbose      # 附各 base 的样例页面
  python tools/qc_base_check.py --selftest     # 校验器自检（已知答案正反例）

约定：写盘产物落库根 `.qc/base_state.json`（经 kb_lib.qc_file，不硬写相对路径）。
"""
import os
import re
import sys
import json
import argparse

try:
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
except Exception:                                  # noqa: BLE001
    pass

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
from kb_lib import read_text, split_frontmatter, qc_file  # noqa: E402

try:
    from ruamel.yaml import YAML as _RuamelYAML
    def _load_yaml(text):
        return _RuamelYAML(typ="safe").load(text)
except Exception:                                  # noqa: BLE001
    import yaml as _pyyaml
    def _load_yaml(text):
        return _pyyaml.safe_load(text)


# --------------------------------------------------------------------------
# 小型 Base 过滤器解释器
# --------------------------------------------------------------------------
class UnknownAtom(Exception):
    """遇到本解释器尚未支持的表达式——**必须显式报出**，不得静默返回 False。

    静默 False 会让「选中集合」凭空缩小，正是本工具要防的那类失效。
    """


def _split_top(expr, op):
    """在**引号/括号之外**的 ` op ` 处切分（Bases 表达式无优先级括号时按此处理）。"""
    out, depth, quote, i, start = [], 0, "", 0, 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if quote:
            if c == quote:
                quote = ""
        elif c in "\"'":
            quote = c
        elif c == "(":
            depth += 1
        elif c == ")":
            depth -= 1
        elif depth == 0 and expr.startswith(op, i):
            out.append(expr[start:i])
            i += len(op)
            start = i
            continue
        i += 1
    out.append(expr[start:])
    return out


def _ext(name):
    return name.rsplit(".", 1)[-1] if "." in name else ""


def field_value(field, ctx):
    """解析 `file.*` 与 frontmatter 字段访问。返回字符串（缺失返回 ""）。"""
    field = field.strip()
    if field == "file.ext":
        return _ext(ctx["basename"])
    if field == "file.name":
        return ctx["basename"]
    if field == "file.basename":
        return ctx["basename"][:-3] if ctx["basename"].endswith(".md") else ctx["basename"]
    if field == "file.path":
        return ctx["path"]
    if field == "file.folder":
        return os.path.dirname(ctx["path"])
    v = ctx["fm"].get(field)
    if v is None:
        return ""
    if isinstance(v, (list, tuple)):
        return ", ".join(str(x) for x in v)
    return str(v)


_ATOM_EQ = re.compile(
    r'^([A-Za-z_][\w.]*)\s*(==|!=)\s*"([^"]*)"$')
_ATOM_BOOL = re.compile(
    r'^([A-Za-z_][\w.]*)\s*(==|!=)\s*(true|false)$')
_ATOM_INFOLDER = re.compile(
    r'^file\.inFolder\(["\']([^"\']*)["\']\)$')
_ATOM_CONTAINS = re.compile(
    r'^([A-Za-z_][\w.]*)[.]contains\(["\']([^"\']*)["\']\)$')
_ATOM_STARTS = re.compile(
    r'^([A-Za-z_][\w.]*)[.](startsWith|endsWith)\(["\']([^"\']*)["\']\)$')
_ATOM_HASPROP = re.compile(
    r'^file\.hasProperty\(["\']([^"\']*)["\']\)$')
_ATOM_HASLINK = re.compile(
    r'^file\.hasLink\(["\']([^"\']*)["\']\)$')


def eval_expr(expr, ctx):
    expr = expr.strip()
    parts = _split_top(expr, " or ")
    if len(parts) > 1:
        return any(eval_expr(p, ctx) for p in parts)
    parts = _split_top(expr, " and ")
    if len(parts) > 1:
        return all(eval_expr(p, ctx) for p in parts)
    if expr.startswith("not "):
        return not eval_expr(expr[4:], ctx)

    m = _ATOM_INFOLDER.match(expr)
    if m:
        folder = m.group(1).strip("/")
        p = ctx["path"]
        return p == folder or p.startswith(folder + "/")
    m = _ATOM_HASPROP.match(expr)
    if m:
        return m.group(1) in ctx["fm"]
    return _eval_atom_rest(expr, ctx)


def _eval_atom_rest(expr, ctx):
    m = _ATOM_HASLINK.match(expr)
    if m:
        return m.group(1) in ctx["text"]
    m = _ATOM_CONTAINS.match(expr)
    if m:
        return m.group(2) in field_value(m.group(1), ctx)
    m = _ATOM_STARTS.match(expr)
    if m:
        v = field_value(m.group(1), ctx)
        op, s = m.group(2), m.group(3)
        return v.startswith(s) if op == "startsWith" else v.endswith(s)
    m = _ATOM_EQ.match(expr)
    if m:
        v, op, s = field_value(m.group(1), ctx), m.group(2), m.group(3)
        return (v == s) if op == "==" else (v != s)
    m = _ATOM_BOOL.match(expr)
    if m:
        v = field_value(m.group(1), ctx).lower()
        want = "true" if m.group(3) == "true" else "false"
        return (v == want) if m.group(2) == "==" else (v != want)
    raise UnknownAtom(expr)


def eval_node(node, ctx):
    """求值一个过滤组：字符串表达式 or {and/or/not: [...]}。"""
    if isinstance(node, str):
        return eval_expr(node, ctx)
    if isinstance(node, dict):
        for key, val in node.items():
            if key == "and":
                return all(eval_node(v, ctx) for v in val)
            if key == "or":
                return any(eval_node(v, ctx) for v in val)
            if key == "not":
                return not any(eval_node(v, ctx) for v in val)
            raise UnknownAtom("dict-key:%s" % key)
    raise UnknownAtom("node-type:%s" % type(node).__name__)


# --------------------------------------------------------------------------
# 扫描
# --------------------------------------------------------------------------
def iter_md(root):
    for dirpath, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d != ".git"]
        for f in files:
            if f.endswith(".md"):
                p = os.path.join(dirpath, f)
                yield os.path.relpath(p, root).replace(os.sep, "/")


def load_pages(root):
    """读入 root 下全部 .md 的 (basename, path, fm, text)。"""
    pages = []
    for rel in iter_md(root):
        try:
            text = read_text(os.path.join(root, rel))
        except Exception:                          # noqa: BLE001
            text = ""
        fm = {}
        try:
            fmtext, _ = split_frontmatter(text)
            fm = _load_yaml(fmtext) if fmtext else {}
            if not isinstance(fm, dict):
                fm = {}
        except Exception:                          # noqa: BLE001
            fm = {}
        pages.append({"basename": os.path.basename(rel), "path": rel,
                      "fm": fm, "text": text})
    return pages


def _norm(v):
    """把过滤器值归一成可比签名字符串（稳定排序，忽略无关格式）。"""
    if isinstance(v, dict):
        return {k: _norm(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_norm(x) for x in v]
    if isinstance(v, str):
        return re.sub(r"\s+", " ", v.strip())
    return v


def base_sig(spec):
    """过滤器「签名」：只有顶层 filters 参与——它变了就意味着选择逻辑被改。"""
    return json.dumps(_norm(spec.get("filters")), ensure_ascii=False, sort_keys=True)


def scan(vault_root):
    """重算全部 `*.base` 的选中集合。返回 list[dict]。"""
    bases = sorted(f for f in os.listdir(vault_root) if f.endswith(".base"))
    pages = load_pages(vault_root)
    results = []
    for bf in bases:
        spec = _load_yaml(read_text(os.path.join(vault_root, bf))) or {}
        flt = spec.get("filters")
        selected, errors = [], []
        if flt is not None:
            for pg in pages:
                try:
                    if eval_node(flt, pg):
                        selected.append(pg["path"])
                except UnknownAtom as e:
                    errors.append(str(e))
                    break
        views = []
        for v in (spec.get("views") or []):
            vf = v.get("filters")
            views.append({"name": v.get("name", ""), "types": v.get("type", ""),
                          "has_view_filter": vf is not None,
                          "view_filter": _norm(vf)})
        results.append({
            "base": bf,
            "sig": base_sig(spec),
            "count": len(selected),
            "selected": selected,
            "views": views,
            "errors": sorted(set(errors))[:3],
        })
    return results


# --------------------------------------------------------------------------
# 字段门禁：会让页面在视图里「删行/留白」的依赖字段
# --------------------------------------------------------------------------
FIELD_RULES = {
    "文献总览.base": ("wiki/sources/", ["year", "journal"]),
    "概念索引.base": ("wiki/concepts/", ["evidence_base"]),
    "实体名录.base": ("wiki/entities/", ["aliases", "summary"]),
    "公众号文集.base": ("raw/", ["source"]),
}


def field_gaps(results, pages_by_path):
    out = []
    for r in results:
        rule = FIELD_RULES.get(r["base"])
        if not rule:
            continue
        prefix, fields = rule
        for p in r["selected"]:
            if not p.startswith(prefix):
                continue
            fm = pages_by_path.get(p, {}).get("fm", {})
            miss = [k for k in fields
                    if not str(fm.get(k) or "").strip()]
            if miss:
                out.append({"base": r["base"], "page": p, "missing": miss})
    return out


# --------------------------------------------------------------------------
def main():
    ap = argparse.ArgumentParser(description="Obsidian Bases 选中集合 + 漂移校验")
    ap.add_argument("--check", action="store_true", help="只比对，不更新基线")
    ap.add_argument("--json", action="store_true", help="机器可读输出")
    ap.add_argument("--verbose", action="store_true", help="附样例页面")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    results = scan(ROOT)
    pages_by_path = {p["path"]: p for p in load_pages(ROOT)}
    gaps = field_gaps(results, pages_by_path)

    state_path = qc_file("base_state.json")
    old = {}
    if os.path.exists(state_path):
        try:
            old = json.loads(read_text(state_path)).get("bases", {})
        except Exception:                          # noqa: BLE001
            old = {}

    sig_changed, count_changed = [], {}
    for r in results:
        prev = old.get(r["base"])
        if prev is None:
            continue
        if prev.get("sig") != r["sig"]:
            sig_changed.append(r["base"])
        if prev.get("count") != r["count"]:
            count_changed[r["base"]] = (prev.get("count"), r["count"])

    if not args.check:
        try:
            os.makedirs(os.path.dirname(state_path), exist_ok=True)
            with open(state_path, "w", encoding="utf-8") as f:
                json.dump({"bases": {r["base"]: {"sig": r["sig"], "count": r["count"]}
                                     for r in results}},
                          f, ensure_ascii=False, indent=2)
        except Exception as e:                     # noqa: BLE001
            print(f"[warn] 基线写入失败：{e}")

    if args.json:
        print(json.dumps({"results": [{k: v for k, v in r.items() if k != "selected"}
                                      for r in results],
                          "samples": {r["base"]: r["selected"][:5] for r in results},
                          "sig_changed": sig_changed,
                          "count_changed": count_changed,
                          "field_gaps": gaps}, ensure_ascii=False, indent=2))
        return 0

    print("=== Obsidian Bases 健康检查 ===")
    for r in results:
        flag = ""
        if r["base"] in sig_changed:
            flag = "  ⚠️ 过滤器签名已变（有人在库外改了选择逻辑）"
        elif r["base"] in count_changed:
            o, n = count_changed[r["base"]]
            flag = f"  ({o} → {n})"
        print(f"  {r['base']:<22} 选中 {r['count']:>5} 页{flag}")
        for v in r["views"]:
            if v["has_view_filter"]:
                print(f"      ⚠️ 视图「{v['name']}」带视图级 filters —— "
                      f"静默收窄高发地，请人工确认：{v['view_filter']}")
        if r["errors"]:
            print(f"      ❌ 过滤器无法解释（计数不可信）：{r['errors']}")
        if args.verbose:
            for s in r["selected"][:5]:
                print(f"        · {s}")

    if sig_changed:
        print(f"\n⚠️  {len(sig_changed)} 个 base 的过滤器签名相对基线已变化：{sig_changed}")
        print("    若非你本人有意修改，请核对是否被误操作（对照 git diff）。")
    if count_changed:
        print("\n计数变化（ingest 后应增长；不增反减须查过滤器）：")
        for b, (o, n) in count_changed.items():
            arrow = "↑" if n > o else "↓"
            print(f"  {b}: {o} {arrow} {n}")
    if gaps:
        by_base = {}
        for g in gaps:
            by_base.setdefault(g["base"], 0)
            by_base[g["base"]] += 1
        print("\n依赖字段缺口（页面仍在，但视图里会留白）：")
        for b, n in by_base.items():
            print(f"  {b}: {n} 页缺 {FIELD_RULES[b][1]}")
    print("\n(只读校验；基线快照见 .qc/base_state.json"
          + ("，本次未更新 --check)" if args.check else "，已更新)"))
    return 0


# --------------------------------------------------------------------------
def selftest():
    """已知答案反算：正例（该选中的选中）+ 反例（不该选中的不选）。"""
    import tempfile
    import shutil
    print("=== qc_base_check --selftest ===")
    ok = True
    tmp = tempfile.mkdtemp(prefix="qc_base_check_")
    try:
        def w(rel, content):
            p = os.path.join(tmp, *rel.split("/"))
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "w", encoding="utf-8") as f:
                f.write(content)

        # 夹具：一个「wiki 内容页」base + 一个「公众号」base
        w("db.base",
          "filters:\n  and:\n    - file.inFolder(\"wiki\")\n    - file.ext == \"md\"\n"
          "    - not:\n        - file.basename == \"index\"\n"
          "        - file.inFolder(\"wiki/.index\")\n")
        w("wx.base",
          "filters:\n  and:\n    - file.ext == \"md\"\n"
          "    - file.inFolder(\"raw\")\n"
          "    - source.contains(\"mp.weixin.qq.com\")\n"
          "    - not:\n        - file.inFolder(\"raw/_park\")\n")
        # 正例
        w("wiki/concepts/A.md", "---\ntype: concept\n---\n# A\n")
        w("wiki/sources/B.md", "---\ntype: source\n---\n# B\n")
        w("wiki/index.md", "---\ntype: meta\n---\n# index\n")          # 反例：basename 排除
        w("wiki/.index/x.md", "---\ntype: x\n---\n")                  # 反例：.index 排除
        w("raw/other.md", "---\ntype: misc\n---\n")                   # 反例：不在 wiki
        w("raw/clippings/W.md", "---\nsource: https://mp.weixin.qq.com/s/x\n---\n")  # 正例
        w("raw/_park/offtopic/P.md", "---\nsource: https://mp.weixin.qq.com/s/y\n---\n")  # 反例：_park 排除
        w("raw/clippings/plain.md", "---\ntitle: nope\n---\n")        # 反例：无 source

        res = {r["base"]: set(r["selected"]) for r in scan(tmp)}
        db = res.get("db.base", set())
        wx = res.get("wx.base", set())

        good = db == {"wiki/concepts/A.md", "wiki/sources/B.md"}
        print(f"  [{'ok' if good else 'FAIL'}] wiki 内容页 base 选中集合（正例2/反例3）：{sorted(db)}")
        ok = ok and good

        good = wx == {"raw/clippings/W.md"}
        print(f"  [{'ok' if good else 'FAIL'}] 公众号 base 选中集合（正例1/反例4）：{sorted(wx)}")
        ok = ok and good

        # 签名漂移：改一个字节的过滤条件 →签名必须变
        s0 = {r["base"]: r["sig"] for r in scan(tmp)}
        w("db.base",
          "filters:\n  and:\n    - file.inFolder(\"wiki\")\n    - file.ext == \"md\"\n"
          "    - not:\n        - file.basename == \"index\"\n        - file.basename == \"tags\"\n"
          "        - file.inFolder(\"wiki/.index\")\n")
        s1 = {r["base"]: r["sig"] for r in scan(tmp)}
        good = s0["db.base"] != s1["db.base"]
        print(f"  [{'ok' if good else 'FAIL'}] 过滤条件变化 → 签名随之变化（漂移可检出）")
        ok = ok and good

        # 未知原子必须抛 UnknownAtom（不得静默 False）
        try:
            eval_expr('regexp.matches("a.*", file.name)', {"basename": "a.md", "path": "a.md",
                                                           "fm": {}, "text": ""})
            bad = False
        except UnknownAtom:
            bad = True
        print(f"  [{'ok' if bad else 'FAIL'}] 未支持的表达式显式报 UnknownAtom（不静默漏选）")
        ok = ok and bad

        # inFolder 不得把同前缀的兄弟目录误收（wiki 不匹配 wiki2/）
        ctx2 = {"basename": "x.md", "path": "wiki2/x.md", "fm": {}, "text": ""}
        good = eval_expr('file.inFolder("wiki")', ctx2) is False
        print(f"  [{'ok' if good else 'FAIL'}] inFolder 不误收同前缀兄弟目录（wiki ≠ wiki2）")
        ok = ok and good
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main())
